std::atomic<bool> stop{false};
std::mutex m;
std::condition_variable cv;

void worker() {
    { std::unique_lock lk(m); cv.wait(lk, [&]{ return stop.load(); }); }
    flush_and_release();                        // phase 2 cleanup
}

std::thread t(worker);
{ std::lock_guard lk(m); stop.store(true); }     // phase 1 under the mutex
cv.notify_one();
t.join();                                       // completion

